import{_ as a,o as r,c as t,S as i}from"./chunks/framework.D1Ss-Xl7.js";const o="/assets/js_async_defer.png",f=JSON.parse('{"title":"JavaScript的加载优化","description":"前端开发中，JavaScript 变得越来越重要，页面载入中，JavaScript 占的比重也更高。不同与别的静态资源，例如图片和 SVG 图标。浏览器在解析 JavaScript 时花的时间要多得多。所以优化 JavaScript 也就变…","frontmatter":{"title":"JavaScript的加载优化","date":"2021-01-23 16:11","comments":true,"archives":2021,"tags":["performance"]},"headers":[],"relativePath":"posts/2021-01-23-javascript-performance/index.md","filePath":"posts/2021/2021-01-23-javascript-performance.md"}'),n={name:"posts/2021-01-23-javascript-performance/index.md"};function c(s,e,p,d,l,h){return r(),t("div",null,[...e[0]||(e[0]=[i('<p>前端开发中，JavaScript 变得越来越重要，页面载入中，JavaScript 占的比重也更高。不同与别的静态资源，例如图片和 SVG 图标。浏览器在解析 JavaScript 时花的时间要多得多。所以优化 JavaScript 也就变得非常重要。</p><h2 id="减少-javascript-的网络传输开销" tabindex="-1">减少 JavaScript 的网络传输开销 <a class="header-anchor" href="#减少-javascript-的网络传输开销" aria-label="Permalink to &quot;减少 JavaScript 的网络传输开销&quot;">​</a></h2><h3 id="only-sending-the-code-a-user-needs" tabindex="-1">Only sending the code a user needs. <a class="header-anchor" href="#only-sending-the-code-a-user-needs" aria-label="Permalink to &quot;Only sending the code a user needs.&quot;">​</a></h3><p>一方面，只加载当前页面需要的 JavaScript 文件，可以使用 webpack 的<a href="https://webpack.js.org/guides/code-splitting/" target="_blank" rel="noreferrer">code-splitting</a>来解决。另一方面，懒加载一些不是必须的 JavaScript 文件。</p><h3 id="minification" tabindex="-1">Minification <a class="header-anchor" href="#minification" aria-label="Permalink to &quot;Minification&quot;">​</a></h3><p>使用<a href="https://github.com/terser/terser" target="_blank" rel="noreferrer">terser</a>来压缩 JavaScript 代码。</p><h3 id="compression" tabindex="-1">Compression <a class="header-anchor" href="#compression" aria-label="Permalink to &quot;Compression&quot;">​</a></h3><p>服务器开启 GZIP 来减少传输的文件大小。</p><h3 id="removing-unused-code" tabindex="-1">Removing unused code. <a class="header-anchor" href="#removing-unused-code" aria-label="Permalink to &quot;Removing unused code.&quot;">​</a></h3><p>针对一些第三方 JavaScript 库，可以使用<a href="https://webpack.js.org/guides/tree-shaking/" target="_blank" rel="noreferrer">Tree Shaking</a>来移除不需要的代码。</p><h3 id="caching-code-to-minimize-network-trips" tabindex="-1">Caching code to minimize network trips. <a class="header-anchor" href="#caching-code-to-minimize-network-trips" aria-label="Permalink to &quot;Caching code to minimize network trips.&quot;">​</a></h3><p>使用 <a href="https://developer.mozilla.org/en-US/docs/Web/HTTP/Headers/ETag" target="_blank" rel="noreferrer">ETag</a>, <a href="https://developer.mozilla.org/en-US/docs/Web/HTTP/Headers/Last-Modified" target="_blank" rel="noreferrer">Last-Modified</a>, <a href="https://developer.mozilla.org/en-US/docs/Web/HTTP/Headers/Cache-Control" target="_blank" rel="noreferrer">Cache-Control</a> 三个配合有效的缓存 JavaScript 文件。</p><h2 id="优化-javascript-下载和执行" tabindex="-1">优化 JavaScript 下载和执行 <a class="header-anchor" href="#优化-javascript-下载和执行" aria-label="Permalink to &quot;优化 JavaScript 下载和执行&quot;">​</a></h2><p>我们可以通过使用 <code>async</code> 或者 <code>defer</code> 来优化 JavaScript 的下载和执行，两个关键字的具体作用看下图：</p><p><img src="'+o+'" alt="js async defer" loading="lazy"></p><h2 id="总结" tabindex="-1">总结 <a class="header-anchor" href="#总结" aria-label="Permalink to &quot;总结&quot;">​</a></h2><p>JavaScript 的优化并没有银弹，要根据具体项目的实际情况来处理。</p><h2 id="参考" tabindex="-1">参考 <a class="header-anchor" href="#参考" aria-label="Permalink to &quot;参考&quot;">​</a></h2><p><a href="https://developer.mozilla.org/en-US/docs/Web/HTTP/Caching" target="_blank" rel="noreferrer">HTTP caching</a></p><p><a href="https://developers.google.com/web/fundamentals/performance/optimizing-content-efficiency/javascript-startup-optimization?hl=en" target="_blank" rel="noreferrer">JavaScript Start-up Optimization</a></p><p><a href="https://developers.google.com/web/fundamentals/performance/optimizing-content-efficiency/loading-third-party-javascript?hl=en" target="_blank" rel="noreferrer">Loading Third-Party JavaScript</a></p>',21)])])}const g=a(n,[["render",c]]);export{f as __pageData,g as default};
